def measure(instance):
    evidence = []
    site = instance.get('site')
    dh = drive_hours(instance)
    limit = DRIVE_LIMIT_HOURS
    feasible = dh <= limit
    # Slack within the budget: positive when feasible, negative when violated.
    # Monotone in the concept (more feasible = more drive-budget headroom).
    slack = limit - dh
    if limit > 0:
        value = slack / limit
    else:
        value = 0.0
    evidence.append(
        "Site '%s' drive_hours=%.2f vs DRIVE_LIMIT_HOURS=%.2f from a home city."
        % (str(site), dh, limit)
    )
    if feasible:
        evidence.append(
            "Within budget: %.2f h of headroom remaining (slack fraction %.3f)."
            % (slack, value)
        )
    else:
        evidence.append(
            "Exceeds budget by %.2f h (slack fraction %.3f) -> constraint violated."
            % (dh - limit, value)
        )
    return {'value': float(value), 'evidence': evidence}
